static SiDigitalFn si_get_digital;
static SiAnalogFn si_get_analog;
static SiMotionFn si_get_motion;
static SiVibrateFn si_vibrate;
static SiSteamApiInitFn si_steam_init;
static SiSteamApiShutdownFn si_steam_shutdown;
static int si_init_attempted_self;
static unsigned long long si_action_set;
static unsigned long long si_digital[SI_DIGITAL_COUNT];
static unsigned long long si_analog[SI_ANALOG_COUNT];
static unsigned long long si_handle;
/* 0 unstarted, 1 resolved-but-not-ready, 2 ready, 3 unavailable */
static int si_state;
static int si_sourced_pad;  /* last poll came from Steam Input actions */

static void si_shutdown_hook(void);
static void si_resolve_handles(void);
static int si_game_dir(char *out, size_t cap) {
    ssize_t length = readlink("/proc/self/exe", out, cap - 64);
    if (length <= 0 || (size_t)length >= cap - 64) return 0;
    out[length] = 0;
    char *slash = strrchr(out, '/');
    if (!slash) return 0;
    *slash = 0;
    return 1;
}

static void *si_lib;
static int si_resolve_symbols(void) {
    struct { const char *name; void **target; } symbols[] = {
        { "SteamAPI_SteamInput_v006", (void **)&si_getter },
        { "SteamAPI_ISteamInput_Init", (void **)&si_init },
        { "SteamAPI_ISteamInput_RunFrame", (void **)&si_run_frame },
        { "SteamAPI_ISteamInput_SetInputActionManifestFilePath", (void **)&si_set_manifest },
        { "SteamAPI_ISteamInput_GetActionSetHandle", (void **)&si_get_set_handle },
        { "SteamAPI_ISteamInput_GetDigitalActionHandle", (void **)&si_get_digital_handle },
        { "SteamAPI_ISteamInput_GetAnalogActionHandle", (void **)&si_get_analog_handle },
        { "SteamAPI_ISteamInput_ActivateActionSet", (void **)&si_activate_set },
        { "SteamAPI_ISteamInput_GetConnectedControllers", (void **)&si_get_connected },
        { "SteamAPI_ISteamInput_GetDigitalActionData", (void **)&si_get_digital },
        { "SteamAPI_ISteamInput_GetAnalogActionData", (void **)&si_get_analog },
        { "SteamAPI_ISteamInput_GetMotionData", (void **)&si_get_motion },
        { "SteamAPI_ISteamInput_TriggerVibration", (void **)&si_vibrate },
        { "SteamAPI_InitSafe", (void **)&si_steam_init },
        { "SteamAPI_Shutdown", (void **)&si_steam_shutdown },
    };
    /* The game dlopens its libsteam_api.so with a local handle, so
     * RTLD_DEFAULT never sees those symbols. Opening the same file by
     * absolute path returns the already-loaded object (just one more
     * reference) and its flat exports resolve directly. */
    if (!si_lib) {
        char game_dir[4096];
        char path[4200];
        if (si_game_dir(game_dir, sizeof(game_dir))) {
            snprintf(path, sizeof(path), "%s/libsteam_api.so", game_dir);
            si_lib = dlopen(path, RTLD_LAZY);
        }
        if (si_lib) loader_note("Steam Input: using the game's libsteam_api.so");
    }
    void *scope = si_lib ? si_lib : RTLD_DEFAULT;
    for (size_t i = 0; i < sizeof(symbols) / sizeof(symbols[0]); ++i) {
        *symbols[i].target = dlsym(scope, symbols[i].name);
        if (!*symbols[i].target) {
            loader_note("Steam Input: symbol missing, staying on the SDL gamecontroller path");
            return 0;
        }
    }
    return 1;
}

/* DSO destructor (not atexit: that drags in a GLIBC_2.34 symbol) - runs
 * at process exit while the steamclient pipe is still alive. */
__attribute__((destructor))
static void si_shutdown_hook(void) {
    if (si_init_attempted_self && si_steam_shutdown && si_state == 2) {
        si_steam_shutdown();
    }
}

/* Lazy: runs from the first pad poll, after the game initialized Steam.
 * The budget is wall time, not polls: the tick runs per frame, so a poll
 * count would expire in seconds while the game is still booting. */
static unsigned si_first_attempt_tick;
static void si_try_init(void) {
    if (si_state == 2 || si_state == 3) return;
    if (!si_getter && !si_resolve_symbols()) { si_state = 3; return; }
    if (!si_first_attempt_tick) si_first_attempt_tick = get_ticks ? get_ticks() : 0;
    if (si_first_attempt_tick && get_ticks() - si_first_attempt_tick > 180000) {
        loader_note("Steam Input: no Steam context after 180s; SDL gamecontroller only");
        si_state = 3;
        return;
    }
    void *instance = si_getter();
    if (!instance && si_steam_init && !si_init_attempted_self) {
        /* Beamdog's Linux build runs Steam in a child process; the main
         * process never calls SteamAPI_Init, so the interface accessors
         * stay null here. Initialize our own context (SteamAPI_InitSafe)
         * with the same lib, user and appid: one extra steamclient pipe. */
        si_init_attempted_self = 1;
        if (si_steam_init()) {
            loader_note("Steam Input: SteamAPI initialized by the bridge");
        } else {
            loader_note("Steam Input: SteamAPI_InitSafe failed; is the Steam client running?");
        }
        instance = si_getter();
    }
    if (!instance) return;              /* SteamAPI not initialized yet */
    if (!si_init(instance, 1)) return;  /* client not ready; retry next poll */
    char game_dir[4096];
    if (si_game_dir(game_dir, sizeof(game_dir))) {
        char manifest[4200];
        snprintf(manifest, sizeof(manifest), "%s/override/steam_input_manifest.vdf", game_dir);
        if (si_set_manifest(instance, manifest)) {
            loader_note("Steam Input: action manifest loaded from override/");
        } else {
            loader_note("Steam Input: manifest not loaded; only user-bound actions will be active");
        }
    }
    si_instance = instance;
    si_state = 2;
    si_resolve_handles();
    unsigned long long handles[16];
    int count = si_get_connected(instance, handles);
    if (count > 0) {
        si_handle = handles[0];
        if (si_action_set) si_activate_set(instance, si_handle, si_action_set);
    }
    char line[128];
    int n = snprintf(line, sizeof(line),
        "Steam Input: ready (set handle %llu, %d controller(s))",
        (unsigned long long)si_action_set, count);
    if (n > 0 && n < (int)sizeof(line)) loader_note(line);
}

/* Action handles can resolve only after the Steam client has registered
 * the manifest and (usually) loaded a configuration for the app, both of
 * which happen asynchronously after SetInputActionManifestFilePath. Re-run
 * the lookups while the set handle is still zero. */
static void si_resolve_handles(void) {
    if (!si_instance) return;
    if (si_action_set) return;
    si_action_set = si_get_set_handle(si_instance, "InGame");
    if (!si_action_set) return;
    for (int i = 0; i < SI_DIGITAL_COUNT; ++i)
        si_digital[i] = si_get_digital_handle(si_instance, SI_DIGITAL_NAMES[i]);
    for (int i = 0; i < SI_ANALOG_COUNT; ++i)
        si_analog[i] = si_get_analog_handle(si_instance, SI_ANALOG_NAMES[i]);
    if (si_handle) si_activate_set(si_instance, si_handle, si_action_set);
    loader_note("Steam Input: action set resolved");
}

static short si_stick_axis(float value) {
    if (value > 1.0f) value = 1.0f;
    if (value < -1.0f) value = -1.0f;
    return (short)(value * 32767.0f);
}

/* Fills the XInput-shaped state from action states. Returns 1 when
 * Steam Input produced input (at least one bound action was active);
 * 0 means: no controller or nothing bound, use the SDL fallback. */
static int si_poll(XINPUT_STATE *state, float *gyro_pitch, float *gyro_yaw) {
    if (si_state != 2) return 0;
    si_run_frame(si_instance, 1);
    si_resolve_handles();
    unsigned long long handles[16];
    int count = si_get_connected(si_instance, handles);
    if (count <= 0) { si_handle = 0; return 0; }
    if (si_handle != handles[0]) {
        si_handle = handles[0];
        if (si_action_set) si_activate_set(si_instance, si_handle, si_action_set);
        loader_note("Steam Input: controller connected");
    }
    int any_active = 0;
    unsigned buttons = 0;
    for (int i = 0; i < SI_DIGITAL_COUNT; ++i) {
        if (!si_digital[i]) continue;
        SiDigitalData data = si_get_digital(si_instance, si_handle, si_digital[i]);
        if (!data.bActive) continue;
        any_active = 1;
        if (data.bState) buttons |= SI_DIGITAL_BITS[i];
    }
    if (!any_active) return 0;
    float move_x = 0, move_y = 0, camera_x = 0, camera_y = 0, left = 0, right = 0;
    float values[SI_ANALOG_COUNT][2] = {{0}};
    for (int i = 0; i < SI_ANALOG_COUNT; ++i) {
        if (!si_analog[i]) continue;
        SiAnalogData data = si_get_analog(si_instance, si_handle, si_analog[i]);
        if (!data.bActive) continue;
        values[i][0] = data.x;
        values[i][1] = data.y;
    }
    move_x = values[0][0]; move_y = values[0][1];
    camera_x = values[1][0]; camera_y = values[1][1];
    left = values[2][0]; right = values[3][0];
    state->Gamepad.wButtons = buttons;
    state->Gamepad.sThumbLX = si_stick_axis(move_x);
    state->Gamepad.sThumbLY = (short)-si_stick_axis(move_y);   /* SI y is down */
    state->Gamepad.sThumbRX = si_stick_axis(camera_x);
    state->Gamepad.sThumbRY = (short)-si_stick_axis(camera_y);
    int l = (int)(left * 255.0f), r = (int)(right * 255.0f);
    state->Gamepad.bLeftTrigger = (unsigned char)(l < 0 ? 0 : l > 255 ? 255 : l);
    state->Gamepad.bRightTrigger = (unsigned char)(r < 0 ? 0 : r > 255 ? 255 : r);
    state->dwPacketNumber = 1;
    if (gyro_pitch && gyro_yaw) {
        SiMotionData motion = si_get_motion(si_instance, si_handle);
        *gyro_pitch = motion.rotVelX;
        *gyro_yaw = motion.rotVelZ;
    }
    return 1;
}

/* The game's main() calls SDL_Init(0x31) - timer, audio, video - and
 * CChitin::initJoysticks is an empty stub in this build, so the joystick
 * and gamecontroller subsystems never come up on their own and
 * SDL_NumJoysticks stays 0 forever. SDL_Init is refcounted, so adding
 * subsystems the game never asked for is safe before or after its own
 * call; without this the pad polling on a real Steam Deck sees nothing. */
static int sdl_init_subsystems(void) {
    const unsigned want = 0x200u | 0x2000u;  /* JOYSTICK | GAMECONTROLLER */
    unsigned (*was_init)(unsigned) = (unsigned (*)(unsigned))((uintptr_t)engine + LX_SDL_WAS_INIT_ADDR);
    if ((was_init(want) & want) == want) return 1;
    int (*init)(unsigned) = (int (*)(unsigned))((uintptr_t)engine + LX_SDL_INIT_ADDR);
    return init(want) == 0;
}

static void open_first_gamepad(void) {
    int count = ((int (*)(void))((uintptr_t)engine + LX_SDL_NUM_JOYSTICKS_ADDR))();
    if (count <= 0 && !sdl_init_subsystems()) return;
    count = ((int (*)(void))((uintptr_t)engine + LX_SDL_NUM_JOYSTICKS_ADDR))();
    int (*is_controller)(int) = (int (*)(int))((uintptr_t)engine + LX_SDL_IS_GAME_CONTROLLER_ADDR);
    for (int index = 0; index < count && index < 16; ++index) {
        if (is_controller(index)) {
            gamepad = sdl_controller_open(index);
            gamepad_device = gamepad ? index : -1;
            gamepad_idle_polls = 0;
            if (gamepad) {
                const char *(*pad_name)(void *) =
                    (const char *(*)(void *))((uintptr_t)engine + LX_SDL_GAME_CONTROLLER_NAME_ADDR);
                char line[256];
                int n = snprintf(line, sizeof(line), "Pad %d: %s", index, pad_name(gamepad));
                if (n > 0 && n < (int)sizeof(line)) loader_note(line);
            }
            return;
        }
    }
}
static int poll_pad(XINPUT_STATE *state) {
    memset(state, 0, sizeof(*state));
    if (!engine) return 0;
    si_try_init();
    si_sourced_pad = si_poll(state, NULL, NULL);
    if (si_sourced_pad) return 1;
    if (!gamepad) open_first_gamepad();
    if (!gamepad) return 0;
    unsigned buttons = 0;
    if (sdl_button(SDL_CB_A)) buttons |= XINPUT_GAMEPAD_A;
    if (sdl_button(SDL_CB_B)) buttons |= XINPUT_GAMEPAD_B;
    if (sdl_button(SDL_CB_X)) buttons |= XINPUT_GAMEPAD_X;
    if (sdl_button(SDL_CB_Y)) buttons |= XINPUT_GAMEPAD_Y;
    if (sdl_button(SDL_CB_BACK)) buttons |= XINPUT_GAMEPAD_BACK;
    if (sdl_button(SDL_CB_START)) buttons |= XINPUT_GAMEPAD_START;
    if (sdl_button(SDL_CB_LEFTSTICK)) buttons |= XINPUT_GAMEPAD_LEFT_THUMB;
    if (sdl_button(SDL_CB_RIGHTSTICK)) buttons |= XINPUT_GAMEPAD_RIGHT_THUMB;
    if (sdl_button(SDL_CB_LEFTSHOULDER)) buttons |= XINPUT_GAMEPAD_LEFT_SHOULDER;
    if (sdl_button(SDL_CB_RIGHTSHOULDER)) buttons |= XINPUT_GAMEPAD_RIGHT_SHOULDER;
    if (sdl_button(SDL_CB_DPUP)) buttons |= XINPUT_GAMEPAD_DPAD_UP;
    if (sdl_button(SDL_CB_DPDOWN)) buttons |= XINPUT_GAMEPAD_DPAD_DOWN;
    if (sdl_button(SDL_CB_DPLEFT)) buttons |= XINPUT_GAMEPAD_DPAD_LEFT;
    if (sdl_button(SDL_CB_DPRIGHT)) buttons |= XINPUT_GAMEPAD_DPAD_RIGHT;
    short left_x = sdl_axis(SDL_CAX_LEFTX), left_y = sdl_axis(SDL_CAX_LEFTY);
    short right_x = sdl_axis(SDL_CAX_RIGHTX), right_y = sdl_axis(SDL_CAX_RIGHTY);
    int left_trigger = sdl_axis(SDL_CAX_TRIGGERLEFT), right_trigger = sdl_axis(SDL_CAX_TRIGGERRIGHT);
    /* SDL reports +Y downwards and 0..32767 triggers; XInput uses +Y upwards
     * and 0..255. */
    state->Gamepad.wButtons = buttons;
    state->Gamepad.sThumbLX = left_x;
    state->Gamepad.sThumbLY = (short)-left_y;
    state->Gamepad.sThumbRX = right_x;
    state->Gamepad.sThumbRY = (short)-right_y;
    state->Gamepad.bLeftTrigger = (unsigned char)(left_trigger < 0 ? 0 : left_trigger >> 7);
    state->Gamepad.bRightTrigger = (unsigned char)(right_trigger < 0 ? 0 : right_trigger >> 7);
    if (buttons || left_x || left_y || right_x || right_y || left_trigger || right_trigger) {
        gamepad_idle_polls = 0;
    } else if (++gamepad_idle_polls > 240) {
        /* Controllers opened once can go away (Bluetooth sleep, Deck re-dock).
         * Re-scan when the pad has stayed silent for a few seconds. */
        ((void (*)(void *))((uintptr_t)engine + LX_SDL_GAME_CONTROLLER_CLOSE_ADDR))(gamepad);
        gamepad = 0;
        gamepad_device = -1;
        gamepad_idle_polls = 0;
    }
    return 1;
}

/* ------------------------------------------------------------------ */
/* SDL event synthesis                                                 */
/* ------------------------------------------------------------------ */

static void mouse_click(void *window, int x, int y, unsigned button) {
    SdlEvent event;
    memset(&event, 0, sizeof(event));
    event.mouse.timestamp = get_ticks();
    event.mouse.window = window_id(window);
    event.mouse.which = CONTROLLER_MOUSE_ID;
    event.mouse.button = (uint8_t)button;
    event.mouse.clicks = 1;
    event.mouse.x = x;
    event.mouse.y = y;
    event.mouse.type = 0x401;
    event.mouse.state = 1;
    push_event(&event);
    event.mouse.type = 0x402;
    event.mouse.state = 0;
    push_event(&event);
}
static void synchronize_pointer(void *window, int x, int y);
static void mouse_double_click(void *window, int x, int y) {
    /* This engine detects a double click from two successive left downs at
     * the same point, not SDL's clicks field (event loop RVA 4a5a85).
     */
    synchronize_pointer(window, x, y);
    mouse_click(window, x, y, 1);
    mouse_click(window, x, y, 1);
}
static void synchronize_pointer(void *window, int x, int y) {
    /* The engine caches hover/object state from motion, separately from the
     * button coordinates. Movement must establish that state before clicking.
     */
    warp_mouse(window, x, y);
    SdlEvent motion;
    memset(&motion, 0, sizeof(motion));
    motion.motion.type = 0x400;
    motion.motion.timestamp = get_ticks();
    motion.motion.window = window_id(window);
    motion.motion.which = CONTROLLER_MOUSE_ID;
    motion.motion.x = x;
    motion.motion.y = y;
    push_event(&motion);
}
static int queue_world_zoom(void *window, int direction, int width, int height, int focused) {
    if (!focused || !window || width <= 0 || height <= 0 || (direction != 1 && direction != -1)) return 0;
    /* Use the stock wheel path. Center its anchor in the world, away from a
     * previously hovered toolbar or scrollable panel. Lua retains cursor hide.
     * Common SDL2 wheel fields are stable; newer fields occupy zero padding in
     * older builds. https://wiki.libsdl.org/SDL2/SDL_MouseWheelEvent
     */
    int x = width / 2, y = height * 3 / 8;
    synchronize_pointer(window, x, y);
    SdlEvent event;
    memset(&event, 0, sizeof(event));
    event.wheel.type = 0x403;
    event.wheel.timestamp = get_ticks();
    event.wheel.window = window_id(window);
    event.wheel.y = direction;
    event.wheel.which = CONTROLLER_MOUSE_ID;
    event.wheel.precise_y = (float)direction;
    event.wheel.mouse_x = x;
    event.wheel.mouse_y = y;
    push_event(&event);
    return 1;
}
static void keyboard_event_marked(void *window, int key, int down, uint32_t marker) {
    SdlEvent event;
    memset(&event, 0, sizeof(event));
    event.key.type = down ? 0x300 : 0x301;
    event.key.timestamp = get_ticks();
    event.key.window = window ? window_id(window) : 0;
    event.key.state = down ? 1 : 0;
    event.key.scancode = get_scancode(key);
    event.key.key = key;
    event.key.unused = marker;
    push_event(&event);
    if (marker == CONTROLLER_MOVIE_KEY_ID) marked_keys_queued = 1;
}
static void keyboard_event(void *window, int key, int down) {
    keyboard_event_marked(window, key, down, 0);
}

static int movie_playing(void) {
    /* Same active-engine/player checks as the Windows build's movie gate.
     * This excludes the looping flame widget and the Movies selection screen. */
    uintptr_t chitin = read_pointer((uintptr_t)engine + E_CHITIN_PTR);
    uintptr_t movie = read_pointer(chitin + CHITIN_MOVIE_PROJECTOR);
    return movie && read_pointer(chitin + CHITIN_ACTIVE_ENGINE) == movie
        && read_pointer(movie + E_MOVIE_PLAYER) != 0;
}
static int movie_skip_edge(int connected, int focused, int playing, unsigned buttons) {
    unsigned a = connected ? buttons & XINPUT_GAMEPAD_A : 0;
    int skip = connected && focused && playing && a && !movie_a_previous;
    movie_a_previous = a;
    return skip;
}
static int sdl_poll_event(SdlEvent *event) {
    if (!sdl_poll_event_fn) return 0;
    return sdl_poll_event_fn(event);
}
static int sdl_push_event(SdlEvent *event) {
    if (!sdl_push_event_fn) return 0;
    return sdl_push_event_fn(event);
}
/* Remove any marked movie-skip keys still queued after playback ended, so a
 * late Escape can never reach the menu. The remaining events are re-queued
 * in their original order; the physical-input watch is muted while
 * replaying so real clicks are not counted twice. */
static void drop_marked_keys(void) {
    if (!marked_keys_queued || movie_playing()) return;
    SdlEvent kept[64];
    int count = 0, scanned = 0;
    SdlEvent event;
    requeue_guard = 1;
    while (scanned < 512 && sdl_poll_event(&event)) {
        ++scanned;
        if ((event.key.type == 0x300 || event.key.type == 0x301)
            && event.key.unused == CONTROLLER_MOVIE_KEY_ID) continue;
        if (count < 64) kept[count++] = event;
    }
    for (int index = 0; index < count; ++index) sdl_push_event(&kept[index]);
    requeue_guard = 0;
    if (scanned < 512 && count < 64) marked_keys_queued = 0;
}
/* Replacement for CChitin::ProcessEvents: the movie-skip A edge is sampled
 * once per frame here, then the original event loop runs. */
static int filtered_process_events(void *chitin) {
    XINPUT_STATE pad;
    int connected = poll_pad(&pad);
    int playing = movie_playing();
    if (movie_skip_edge(connected, foreground_game(), playing, pad.Gamepad.wButtons)) {
        void *window = keyboard_focus();
        if (!window) window = mouse_focus();
        if (window) {
            keyboard_event_marked(window, 27, 1, CONTROLLER_MOVIE_KEY_ID);
            keyboard_event_marked(window, 27, 0, CONTROLLER_MOVIE_KEY_ID);
        }
    }
    if (marked_keys_queued && !playing) drop_marked_keys();
    return original_process_events(chitin);
}

#include "nearby_targets.h"

/* ------------------------------------------------------------------ */
/* camera                                                              */
/* ------------------------------------------------------------------ */

static uintptr_t follow_owner_world;
static int32_t follow_owner_id = -1;
static int follow_owned;
static int controller_camera_follow(int mode, int focused) {
    uintptr_t chitin = read_pointer((uintptr_t)engine + E_CHITIN_PTR);
    uintptr_t world = read_pointer(chitin + CHITIN_WORLD_SCREEN);
    int32_t current = -1;
    int result = 0;
    if (!world || !read_memory(world + 0xa58, &current, 4) || !point_is_writable(world + 0xa58)) return 0;
    if (mode == 0) {
        if (follow_owned && follow_owner_world == world && current == follow_owner_id) {
            int32_t unlocked = -1;
            memcpy((void *)(world + 0xa58), &unlocked, 4);
            result = 1;
        }
        follow_owned = 0;
    } else if (focused && read_pointer(chitin + CHITIN_ACTIVE_ENGINE) == world && mode == 1 && current == -1) {
        uintptr_t game, area, video;
        uint32_t leader = UINT32_MAX;
        int32_t origin[2];
        if (interaction_context(&game, &area, &video) && selected_origin(game, area, &leader, origin)) {
            int32_t lock = (int32_t)leader;
            memcpy((void *)(world + 0xa58), &lock, 4);
            follow_owner_world = world;
            follow_owner_id = lock;
            follow_owned = 1;
            result = 1;
        }
    } else if (focused && read_pointer(chitin + CHITIN_ACTIVE_ENGINE) == world && mode == 2) {
        /* Explicit manual camera input takes priority over any follow lock,
         * including one left behind by an earlier plugin/selection change. */
        int32_t unlocked = -1;
        memcpy((void *)(world + 0xa58), &unlocked, 4);
        follow_owned = 0;
        result = 1;
    }
    int32_t after = -1;
    read_memory(world + 0xa58, &after, 4);
    log_runtime(19, mode, current, after);
    return result;
}
static int pan_world_camera(int dx, int dy, int width, int height, int focused) {
    if (!focused || !set_world_view || width <= 0 || height <= 0
        || dx < -128 || dx > 128 || dy < -128 || dy > 128 || (!dx && !dy)) return 0;
    uintptr_t chitin = read_pointer((uintptr_t)engine + E_CHITIN_PTR);
    uintptr_t world = read_pointer(chitin + CHITIN_WORLD_SCREEN);
    uintptr_t game, area, video;
    if (!world || read_pointer(chitin + CHITIN_ACTIVE_ENGINE) != world || !interaction_context(&game, &area, &video)) return 0;
    int32_t current[2], dimensions[2];
    uint16_t rw = 0, rh = 0;
    float zoom = 0;
    if (!read_memory(area + 0x698, current, 8) || !read_memory(video + 0x150, dimensions, 8)
        || !read_memory(area + 0xa14, &zoom, 4)
        || !read_memory((uintptr_t)engine + E_REF_WIDTH, &rw, 2)
        || !read_memory((uintptr_t)engine + E_REF_HEIGHT, &rh, 2)
        || dimensions[0] <= 0 || dimensions[1] <= 0 || !rw || !rh
        || !isfinite(zoom) || zoom < 0.125f || zoom > 8.0f
        || current[0] < -32768 || current[0] > 32767 || current[1] < -32768 || current[1] > 32767) return 0;
    /* Mirror the stock view-point command (CScreenWorld::StartScroll with a
     * zero duration). Its renderer clamps to the area limits and handles
     * invalidation. Convert client pixels to world units using the stock
     * point projection.
     */
    int32_t target[2] = {current[0] + (int32_t)lround((double)dx * rw * zoom / dimensions[0]),
                         current[1] + (int32_t)lround((double)dy * rh * zoom / dimensions[1])};
    uint64_t point;
    memcpy(&point, target, 8);
    set_world_view((void *)world, point, 0);
    return 1;
}

/* ------------------------------------------------------------------ */
/* dispatch contract (identical to the Windows bridge)                 */
/* ------------------------------------------------------------------ */

/* Operation 0 polls; 1 warps only this game's cursor; 2 queues a mouse click;
 * 3 queues one keyboard edge; 4 synchronizes hover before a steering click;
 * 5 hides/restores the game's cursor for controller movement.
 * All SDL mutations are queued for the next game event loop, on the UI thread.
 */
static int dispatch(lua_State *state) {
    if (!event_watch_installed && add_event_watch) {
        /* First Lua poll occurs after the game's SDL startup. */
        add_event_watch(watch_physical_input, NULL);
        event_watch_installed = 1;
    }
    int operation = (int)to_number(state, 1, NULL);
    int a = (int)to_number(state, 2, NULL);
    int b = (int)to_number(state, 3, NULL);
    int c = (int)to_number(state, 4, NULL);
    int focused = foreground_game();
    if (!focused) set_drive_cursor_hidden(0);
    else if (cursor_hidden_by_mod) set_drive_cursor_hidden(1);
    if (operation == 5) set_drive_cursor_hidden(focused && a != 0);
    void *window = mouse_focus();
    if (!window) window = keyboard_focus();
    int x = 0, y = 0, width = 0, height = 0;
    mouse_state(&x, &y);
    if (window) window_size(window, &width, &height);
    if (operation == 12) { log_runtime(operation, a, b, c); if (a == 200) log_party_members(); }
    if ((operation >= 6 && operation <= 8) || operation == 15) return dispatch_nearby(state, operation, (uint32_t)a, b, window, width, height, focused);
    if (operation >= 9 && operation <= 11) return dispatch_steering(state, operation, a, b, focused, c == 1);
    if (operation == 16) {
        int queued = queue_world_zoom(window, a, width, height, focused);
        log_runtime(operation, a, 0, queued);
        push_number(state, queued);
        return 1;
    }
    if (operation == 18) {
        int moved = pan_world_camera(a, b, width, height, focused);
        log_runtime(18, a, b, moved);
        push_number(state, moved);
        return 1;
    }
    if (operation == 19) { push_number(state, controller_camera_follow(a, focused)); return 1; }
    if (operation == 20) {
        /* Haptics through Steam Input: a = left, b = right intensity. */
        int fired = 0;
        if (si_state == 2 && si_handle) {
            unsigned left = a < 0 ? 0 : (a > 65535 ? 65535 : a);
            unsigned right = b < 0 ? 0 : (b > 65535 ? 65535 : b);
            si_vibrate(si_instance, si_handle, (unsigned short)left, (unsigned short)right);
            fired = 1;
        }
        push_number(state, fired);
        return 1;
    }
    if (window && width > 0 && height > 0) {
        if (focused && operation == 1) {
            if (a < 0) a = 0;
            if (b < 0) b = 0;
            if (a >= width) a = width - 1;
            if (b >= height) b = height - 1;
            warp_mouse(window, a, b);
        } else if (focused && operation == 17 && a >= 0 && b >= 0 && a < width && b < height) {
            mouse_double_click(window, a, b);
            log_runtime(operation, a, b, 1);
        } else if (focused && (operation == 2 || operation == 4) && a >= 0 && b >= 0 && a < width && b < height) {
            if (operation == 4) synchronize_pointer(window, a, b);
            mouse_click(window, a, b, c == 3 ? 3 : 1);
        } else if (operation == 3 && (focused || !b) && a > 0) {
            keyboard_event(window, a, b != 0);
            log_runtime(operation, a, b, c);
        }
    }
    if (!window && operation == 3 && !b && a > 0) keyboard_event(NULL, a, 0);
    XINPUT_STATE pad;
    float gyro_pitch = 0.0f, gyro_yaw = 0.0f;
    int connected = poll_pad(&pad);
    /* Extra returns beyond the Windows bridge's 20: Steam Input active
     * and gyro angular velocity (deg/s). The Lua side ignores them until
     * it asks, so the shared contract stays intact. */
    int si_active = si_sourced_pad;
    if (si_state == 2 && si_handle) {
        SiMotionData motion = si_get_motion(si_instance, si_handle);
        gyro_pitch = motion.rotVelX;
        gyro_yaw = motion.rotVelZ;
    }
    if (!focused) memset(&pad.Gamepad, 0, sizeof(pad.Gamepad));
    double px = 0, py = 0;
    int position_valid = focused && player_screen_position(&px, &py);
    int32_t selected_count = 0;
    uintptr_t chitin = read_pointer((uintptr_t)engine + E_CHITIN_PTR);
    uintptr_t game = read_pointer(chitin + CHITIN_GAME);
    if (!read_memory(game + 0xa2b0, &selected_count, 4) || selected_count < 0 || selected_count > 6) selected_count = 0;
    double values[23] = {
        connected, pad.Gamepad.wButtons, pad.Gamepad.sThumbLX, pad.Gamepad.sThumbLY,
        pad.Gamepad.sThumbRX, pad.Gamepad.sThumbRY, pad.Gamepad.bLeftTrigger,
        pad.Gamepad.bRightTrigger, x, y, width, height, get_ticks(), focused,
        px, py, position_valid, selected_count,
        (uint32_t)__atomic_load_n(&physical_click_serial, __ATOMIC_RELAXED), movie_playing(),
        si_active, gyro_pitch, gyro_yaw
    };
    for (size_t index = 0; index < 23; ++index) push_number(state, values[index]);
    return 23;
}

/* ------------------------------------------------------------------ */
/* engine fingerprint                                                  */
/* ------------------------------------------------------------------ */

/* Compact SHA-256 (FIPS 180-4) so the bridge depends on no crypto library:
 * the game links OpenSSL 1.0, which is not safe to bind against from here.
 * This is the standard public-domain compact implementation. */
struct sha256_ctx { uint32_t state[8]; uint64_t bits; unsigned char buffer[64]; size_t used; };
static const uint32_t sha256_k[64] = {
    0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
    0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
    0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
    0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
    0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
    0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
    0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
    0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u,
};
static uint32_t ror32(uint32_t value, unsigned count) { return (value >> count) | (value << (32 - count)); }
static void sha256_compress(struct sha256_ctx *ctx, const unsigned char block[64]) {
    uint32_t w[64];
    for (int i = 0; i < 16; ++i)
        w[i] = ((uint32_t)block[i*4] << 24) | ((uint32_t)block[i*4+1] << 16) | ((uint32_t)block[i*4+2] << 8) | (uint32_t)block[i*4+3];
    for (int i = 16; i < 64; ++i) {
        uint32_t s0 = ror32(w[i-15], 7) ^ ror32(w[i-15], 18) ^ (w[i-15] >> 3);
        uint32_t s1 = ror32(w[i-2], 17) ^ ror32(w[i-2], 19) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=ctx->state[0],b=ctx->state[1],c=ctx->state[2],d=ctx->state[3];
    uint32_t e=ctx->state[4],f=ctx->state[5],g=ctx->state[6],h=ctx->state[7];
    for (int i = 0; i < 64; ++i) {
        uint32_t s1 = ror32(e, 6) ^ ror32(e, 11) ^ ror32(e, 25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + s1 + ch + sha256_k[i] + w[i];
        uint32_t s0 = ror32(a, 2) ^ ror32(a, 13) ^ ror32(a, 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = s0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    ctx->state[0]+=a; ctx->state[1]+=b; ctx->state[2]+=c; ctx->state[3]+=d;
    ctx->state[4]+=e; ctx->state[5]+=f; ctx->state[6]+=g; ctx->state[7]+=h;
}
static void sha256_init(struct sha256_ctx *ctx) {
    static const uint32_t initial[8] = {0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};
    memcpy(ctx->state, initial, sizeof(initial));
    ctx->bits = 0; ctx->used = 0;
}
static void sha256_update(struct sha256_ctx *ctx, const void *data, size_t length) {
    ctx->bits += (uint64_t)length * 8u;
    const unsigned char *p = data;
    while (length) {
        size_t take = 64 - ctx->used;
        if (take > length) take = length;
        memcpy(ctx->buffer + ctx->used, p, take);
        ctx->used += take; p += take; length -= take;
        if (ctx->used == 64) { sha256_compress(ctx, ctx->buffer); ctx->used = 0; }
    }
}
static void sha256_final(struct sha256_ctx *ctx, unsigned char out[32]) {
    /* Padding: 0x80, zeros, then the 64-bit big-endian bit length, so the
     * total is a multiple of 64. The counter was already maintained by
     * sha256_update, so the tail is fed without recounting. */
    size_t pad = (ctx->used < 56) ? (56 - ctx->used) : (120 - ctx->used);
    static const unsigned char padding[64] = {0x80};
    uint64_t bits = ctx->bits;
    sha256_update(ctx, padding, pad);
    ctx->bits = bits;
    unsigned char length[8];
    for (int i = 0; i < 8; ++i) length[i] = (unsigned char)(bits >> (56 - 8 * i));
    sha256_update(ctx, length, 8);
    ctx->bits = bits;
    for (int i = 0; i < 8; ++i) {
        out[i*4]   = (unsigned char)(ctx->state[i] >> 24);
        out[i*4+1] = (unsigned char)(ctx->state[i] >> 16);
        out[i*4+2] = (unsigned char)(ctx->state[i] >> 8);
        out[i*4+3] = (unsigned char)(ctx->state[i]);
    }
}
static int supported_executable(void) {
    int fd = open("/proc/self/exe", O_RDONLY | O_CLOEXEC);
    if (fd < 0) return 0;
    struct sha256_ctx ctx;
    sha256_init(&ctx);
    unsigned char chunk[65536];
    for (;;) {
        ssize_t got = read(fd, chunk, sizeof(chunk));
        if (got < 0) { close(fd); return 0; }
        if (got == 0) break;
        sha256_update(&ctx, chunk, (size_t)got);
    }
    close(fd);
    unsigned char digest[32];
    sha256_final(&ctx, digest);
    const char *expected = LX_ENGINE_SHA256;
    char hex[65];
    static const char digits[] = "0123456789abcdef";
    for (int i = 0; i < 32; ++i) {
        hex[i*2] = digits[digest[i] >> 4];
        hex[i*2+1] = digits[digest[i] & 15];
    }
    hex[64] = 0;
    return memcmp(hex, expected, 64) == 0;
}

/* ------------------------------------------------------------------ */
/* code patching                                                       */
/* ------------------------------------------------------------------ */

static void absolute_jump(unsigned char *destination, const void *function) {
    destination[0] = 0xff;
    destination[1] = 0x25;
    memset(destination + 2, 0, 4);
    memcpy(destination + 6, &function, sizeof(function));
}
/* 12-byte absolute jump for sites with less than 14 stealable bytes.
 * It clobbers rax, so it is only valid at function entries whose original
 * prologue does not read the incoming rax. */
static void absolute_jump12(unsigned char *destination, const void *function) {
    destination[0] = 0x48;
    destination[1] = 0xb8;
    memcpy(destination + 2, &function, sizeof(function));
    destination[10] = 0xff;
    destination[11] = 0xe0;
}
static int hex_value(char digit) {
    if (digit >= '0' && digit <= '9') return digit - '0';
    if (digit >= 'a' && digit <= 'f') return digit - 'a' + 10;
    return -1;
}
static int parse_hex(const char *text, unsigned char *out, size_t bytes) {
    for (size_t i = 0; i < bytes; ++i) {
        int hi = hex_value(text[i*2]), lo = hex_value(text[i*2+1]);
        if (hi < 0 || lo < 0) return 0;
        out[i] = (unsigned char)((hi << 4) | lo);
    }
    return 1;
}
/* Allocate a gate page, copy the relocation-free instructions into it and
 * return the executable address. */
static unsigned char *make_gate(const unsigned char *code, size_t bytes) {
    unsigned char *gate = mmap(NULL, 128, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (gate == MAP_FAILED) return NULL;
    memcpy(gate, code, bytes);
    if (mprotect(gate, 128, PROT_READ | PROT_EXEC) != 0) { munmap(gate, 128); return NULL; }
    return gate;
}
static int patch_checked_bytes(unsigned char *target, const char *expected_hex, size_t size, void *replacement) {
    unsigned char expected[64];
    if (size > sizeof(expected) || size < 14 || !parse_hex(expected_hex, expected, size)) return 0;
    if (memcmp(target, expected, size) != 0) return 0;
    uintptr_t page = (uintptr_t)target & ~(uintptr_t)0xfff;
    size_t span = ((uintptr_t)target + size - page + 0xfff) & ~(size_t)0xfff;
    if (mprotect((void *)page, span, PROT_READ | PROT_WRITE | PROT_EXEC) != 0) return 0;
    memset(target, 0x90, size);
    absolute_jump(target, replacement);
    mprotect((void *)page, span, PROT_READ | PROT_EXEC);
    __builtin___clear_cache((char *)target, (char *)target + size);
    return 1;
}

/* CChitin::ProcessEvents: endbr64; push r14; push r13; push r12;
 * lea r12, CWarp::OnEvent(%rip). The lea is position dependent, so the
 * trampoline rebuilds it as an immediate; entry+17 is the original
 * push rbp. The gate is built and made executable before the entry is
 * patched, so the trampoline always contains pristine instructions. */
static int install_process_events_filter(void) {
    unsigned char trampoline[64];
    size_t used = 0;
    trampoline[used++] = 0x41; trampoline[used++] = 0x56;  /* push r14 */
    trampoline[used++] = 0x41; trampoline[used++] = 0x55;  /* push r13 */
    trampoline[used++] = 0x41; trampoline[used++] = 0x54;  /* push r12 */
    trampoline[used++] = 0x49; trampoline[used++] = 0xba;  /* movabs r12, imm64 */
    const void *on_event = engine + LX_CWARP_ON_EVENT_ADDR;
    memcpy(trampoline + used, &on_event, 8); used += 8;
    absolute_jump(trampoline + used, engine + LX_PROCESS_EVENTS_ADDR + LX_PROCESS_EVENTS_PROLOGUE_SIZE);
    used += 14;
    unsigned char *gate = make_gate(trampoline, used);
    if (!gate) return 0;
    original_process_events = (int (*)(void *))gate;
    return patch_checked_bytes(engine + LX_PROCESS_EVENTS_ADDR,
        LX_PROCESS_EVENTS_PROLOGUE, LX_PROCESS_EVENTS_PROLOGUE_SIZE,
        (void *)filtered_process_events);
}

/* CVidMode::SetPointer(CVidCell*, CResRef, uchar, int): the first 27 bytes
 * are plain pushes/moves/sub with no RIP-relative operands, so the
 * trampoline replays the pristine prologue bytes from the recorded hex and
 * jumps back to entry+27. */
static int filtered_set_pointer(void *video, void *cell, uint64_t resref, unsigned char flag, int mode) {
    if (cursor_hidden_by_mod && cell) {
        /* Suppress the cursor update and remember the last request so the
         * restore path can re-issue it. */
        desired_video = video;
        desired_pointer = cell;
        desired_resref = resref;
        desired_flag = flag;
        desired_mode = mode;
        return 1;
    }
    return original_set_pointer(video, cell, resref, flag, mode);
}
static int install_set_pointer_filter(void) {
    unsigned char original[32];
    if (LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE > sizeof(original)
        || !parse_hex(LX_CVIDEO_SET_POINTER_PROLOGUE, original, LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE))
        return 0;
    unsigned char trampoline[64];
    memcpy(trampoline, original, LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE);
    absolute_jump(trampoline + LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE,
        engine + LX_CVIDEO_SET_POINTER_ADDR + LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE);
    unsigned char *gate = make_gate(trampoline, LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE + 14);
    if (!gate) return 0;
    original_set_pointer = (int (*)(void *, void *, uint64_t, unsigned char, int))gate;
    return patch_checked_bytes(engine + LX_CVIDEO_SET_POINTER_ADDR,
        LX_CVIDEO_SET_POINTER_PROLOGUE, LX_CVIDEO_SET_POINTER_PROLOGUE_SIZE,
        (void *)filtered_set_pointer);
}

static void set_drive_cursor_hidden(int hide) {
    if (hide && !cursor_hidden_by_mod) {
        cursor_visibility_before_drive = show_cursor(-1);
        cursor_hidden_by_mod = 1;
    }
    if (hide) {
        show_cursor(0);
    } else if (cursor_hidden_by_mod) {
        cursor_hidden_by_mod = 0;
        if (desired_video && original_set_pointer)
            original_set_pointer(desired_video, desired_pointer, desired_resref, desired_flag, desired_mode);
        desired_video = desired_pointer = 0;
        show_cursor(cursor_visibility_before_drive > 0 ? 1 : 0);
    }
}

/* ------------------------------------------------------------------ */
/* Lua registration                                                    */
/* ------------------------------------------------------------------ */

static void (*lua_setglobal_fn)(void *, const char *);
static int bridge_registered;

static FILE *loader_log;
static void loader_note(const char *message) {
    if (!loader_log) return;
    fwrite(message, 1, strlen(message), loader_log);
    fputc('\n', loader_log);
    fflush(loader_log);
}
static FILE *open_side_log(const char *name) {
    char path[4096];
    ssize_t length = readlink("/proc/self/exe", path, sizeof(path) - 64);
    if (length <= 0 || (size_t)length >= sizeof(path) - 64) return NULL;
    char *slash = strrchr(path, '/');
    if (!slash) return NULL;
    strcpy(slash + 1, name);
    return fopen(path, "we");
}

/* Register the dispatch closure as the PSTPadNative global, exactly like the
 * Windows bridge's startup hook does. The M_PSTPAD.lua environment resolves
 * engine-registered globals, which is how the injected DLL was found. */
static void register_bridge(void *state) {
    if (!state || bridge_registered || !push_closure || !lua_setglobal_fn) return;
    push_closure(state, dispatch, 0);
    lua_setglobal_fn(state, "PSTPadNative");
    bridge_registered = 1;
}

/* bootstrapLua(): endbr64; sub rsp,8; call luaL_newstate. The call is
 * position dependent, so the trampoline re-issues it as an absolute call;
 * entry+13 resumes at the `lea luaopen_base` instruction. The wrapper runs
 * after the original returns, when g_lua exists and the libraries are open.
 */
static void *(*bootstrap_trampoline)(void);
static void *wrapped_bootstrap(void) {
    void *state = bootstrap_trampoline();
    register_bridge(*(void **)(engine + LX_G_LUA_ADDR));
    loader_note(bridge_registered
        ? "bootstrapLua returned; PSTPadNative registered"
        : "bootstrapLua returned; registration skipped");
    return state;
}
static int install_bootstrap_hook(void) {
    unsigned char trampoline[64];
    size_t used = 0;
    trampoline[used++] = 0x48; trampoline[used++] = 0x83; trampoline[used++] = 0xec; trampoline[used++] = 0x08;  /* sub rsp,8 */
    trampoline[used++] = 0x49; trampoline[used++] = 0xbb;  /* movabs r11, luaL_newstate */
    const void *newstate = engine + LX_LUAL_NEWSTATE_ADDR;
    memcpy(trampoline + used, &newstate, 8); used += 8;
    trampoline[used++] = 0x41; trampoline[used++] = 0xff; trampoline[used++] = 0xd3;  /* call r11 */
    absolute_jump(trampoline + used, engine + LX_BOOTSTRAP_LUA_ADDR + 13);
    used += 14;
    unsigned char *gate = make_gate(trampoline, used);
    if (!gate) return 0;
    bootstrap_trampoline = (void *(*)(void))gate;
    /* The prologue is only 13 bytes: the 12-byte rax-clobbering jump is safe
     * here because bootstrapLua takes no arguments and never reads the
     * incoming rax. The 13th byte stays dead: execution always enters
     * through the jump. */
    unsigned char expected[64];
    unsigned char *entry = engine + LX_BOOTSTRAP_LUA_ADDR;
    if (!parse_hex(LX_BOOTSTRAP_LUA_PROLOGUE, expected, 13) || memcmp(entry, expected, 13) != 0)
        return 0;
    uintptr_t page = (uintptr_t)entry & ~(uintptr_t)0xfff;
    size_t span = ((uintptr_t)entry + 12 - page + 0xfff) & ~(size_t)0xfff;
    if (mprotect((void *)page, span, PROT_READ | PROT_WRITE | PROT_EXEC) != 0) return 0;
    absolute_jump12(entry, (void *)wrapped_bootstrap);
    mprotect((void *)page, span, PROT_READ | PROT_EXEC);
    __builtin___clear_cache((char *)entry, (char *)entry + 12);
    return 1;
}

/* uiDoFile(const char*): endbr64; push r15; mov rdx,rdi; lea rsi,fmt(%rip);
 * push r14. The lea is position dependent, so the trampoline rebuilds it as
 * an immediate; entry+18 resumes at push r13. The wrapper logs every Lua
 * chunk the engine executes, which makes "the mod's Lua never ran"
 * diagnosable from controller-loader.log. */
static int (*ui_do_file_trampoline)(const char *);
/* Survey the state's globals right before the mod's own chunk runs: this
 * uses the same load path the engine does, so the visibility question
 * ("can the M_ chunk see PSTPadNative?") gets a logged answer. */
static void survey_globals(void) {
    void *L = *(void **)(engine + LX_G_LUA_ADDR);
    if (!L) return;
    int (*loadbuffer)(void *, const char *, size_t, const char *, const char *) =
        (int (*)(void *, const char *, size_t, const char *, const char *))(engine + 0x6a5850);
    int (*pcall)(void *, int, int, int) = (int (*)(void *, int, int, int))(engine + 0x6a2b50);
    const char *(*tolstring)(void *, int, size_t *) = (const char *(*)(void *, int, size_t *))(engine + 0x6a1050);
    void (*settop)(void *, int) = (void (*)(void *, int))(engine + 0x69fe40);
    static const char chunk[] =
        "local a, b, c, d, e = PSTPadNative(0, 0, 0, 0)\n"
        "return 'PSTPadNative=' .. type(PSTPadNative)"
        " .. ' call=' .. tostring(a) .. ',' .. tostring(b) .. ',' .. tostring(d) .. ',' .. tostring(e)";
    if (loadbuffer(L, chunk, sizeof(chunk) - 1, "=survey", NULL) != 0) {
        loader_note("survey: loadbuffer failed");
        return;
    }
    if (pcall(L, 0, 1, 0) != 0) {
        size_t len = 0;
        const char *err = tolstring(L, -1, &len);
        char line[256];
        int n = snprintf(line, sizeof(line), "survey: pcall failed: %.*s", (int)(len > 200 ? 200 : len), err ? err : "?");
        if (n > 0) loader_note(line);
        settop(L, 0);
        return;
    }
    size_t len = 0;
    const char *result = tolstring(L, -1, &len);
    char line[256];
    int n = snprintf(line, sizeof(line), "survey: %.*s", (int)(len > 220 ? 220 : len), result ? result : "?");
    if (n > 0) loader_note(line);
    settop(L, 0);
}
static int wrapped_ui_do_file(const char *name) {
    if (name) {
        char line[512];
        int length = snprintf(line, sizeof(line), "Lua chunk: %s", name);
        if (length > 0 && length < (int)sizeof(line)) loader_note(line);
        if (strcmp(name, "M_PSTPAD") == 0) survey_globals();
    }
    return ui_do_file_trampoline(name);
}
static int install_ui_do_file_logger(void) {
    unsigned char trampoline[64];
    size_t used = 0;
    trampoline[used++] = 0x41; trampoline[used++] = 0x57;                    /* push r15 */
    trampoline[used++] = 0x48; trampoline[used++] = 0x89; trampoline[used++] = 0xfa;  /* mov rdx,rdi */
    trampoline[used++] = 0x48; trampoline[used++] = 0xbe;                    /* movabs rsi, imm64 */
    const void *format = engine + 0xbacafd;
    memcpy(trampoline + used, &format, 8); used += 8;
    trampoline[used++] = 0x41; trampoline[used++] = 0x56;                    /* push r14 */
    absolute_jump(trampoline + used, engine + LX_UI_DO_FILE_ADDR + 18);
    used += 14;
    unsigned char *gate = make_gate(trampoline, used);
    if (!gate) return 0;
    ui_do_file_trampoline = (int (*)(const char *))gate;
    return patch_checked_bytes(engine + LX_UI_DO_FILE_ADDR,
        LX_UI_DO_FILE_PROLOGUE, LX_UI_DO_FILE_PROLOGUE_SIZE,
        (void *)wrapped_ui_do_file);
}

/* ------------------------------------------------------------------ */
/* profile and initialization                                          */
/* ------------------------------------------------------------------ */

/* The mod must run on its isolated profile; the Windows launcher enforced
 * this by refusing to start without the Controller Lab engine.lua. */
static int controller_lab_profile(void) {
    char path[4096];
    ssize_t length = readlink("/proc/self/exe", path, sizeof(path) - 32);
    if (length <= 0 || (size_t)length >= sizeof(path) - 32) return 0;
    char *slash = strrchr(path, '/');
    if (!slash) return 0;
    strcpy(slash + 1, "engine.lua");
    FILE *file = fopen(path, "rb");
    if (!file) return 0;
    char text[4096] = {0};
    size_t got = fread(text, 1, sizeof(text) - 1, file);
    fclose(file);
    (void)got;
    return strstr(text, "engine_name=\"Planescape Torment - Controller Lab\"") != NULL;
}

static int initialize_bindings(void) {
    struct phdr_scan scan = {0};
    dl_iterate_phdr(phdr_callback, &scan);
    if (!scan.found || !scan.base) return 0;
    engine = scan.base;
    engine_image_size = scan.size;
    if (!supported_executable()) return 0;
    if (!open_mem_fd()) return 0;

    push_closure = (PushClosure)(engine + LX_LUA_PUSHCCLOSURE_ADDR);
    push_number = (PushNumber)(engine + LX_LUA_PUSHNUMBER_ADDR);
    to_number = (ToNumber)(engine + LX_LUA_TONUMBERX_ADDR);
    lua_setglobal_fn = (void (*)(void *, const char *))(engine + LX_LUA_SETGLOBAL_ADDR);
    group_clear_actions = (void (*)(void *))(engine + LX_GROUP_CLEAR_ACTIONS_ADDR);
    group_move = (void (*)(void *, uint64_t, int, uint16_t, uint64_t))(engine + LX_GROUP_MOVE_ADDR);
    prepare_group_run = (void (*)(void *))(engine + LX_PREPARE_GROUP_RUN_ADDR);
    clear_pending_actions = (void (*)(void *, int))(engine + LX_CLEAR_PENDING_ACTIONS_ADDR);
    request_move_path = (uint16_t (*)(void *, const int32_t *))(engine + LX_REQUEST_MOVE_PATH_ADDR);
    set_world_view = (void (*)(void *, uint64_t, int16_t))(engine + LX_SET_WORLD_VIEW_ADDR);

    mouse_focus = (GetMouseFocus)(engine + LX_SDL_GET_MOUSE_FOCUS_ADDR);
    keyboard_focus = (GetMouseFocus)(engine + LX_SDL_GET_KEYBOARD_FOCUS_ADDR);
    mouse_state = (GetMouseState)(engine + LX_SDL_GET_MOUSE_STATE_ADDR);
    window_size = (GetWindowSize)(engine + LX_SDL_GET_WINDOW_SIZE_ADDR);
    window_id = (GetWindowId)(engine + LX_SDL_GET_WINDOW_ID_ADDR);
    get_ticks = (GetTicks)(engine + LX_SDL_GET_TICKS_ADDR);
    warp_mouse = (WarpMouse)(engine + LX_SDL_WARP_MOUSE_IN_WINDOW_ADDR);
    push_event = (PushEvent)(engine + LX_SDL_PUSH_EVENT_ADDR);
    sdl_poll_event_fn = (PollEventFn)(engine + LX_SDL_POLL_EVENT_ADDR);
    sdl_push_event_fn = (PushEventFn)(engine + LX_SDL_PUSH_EVENT_ADDR);
    get_scancode = (GetScancode)(engine + LX_SDL_GET_SCANCODE_FROM_KEY_ADDR);
    show_cursor = (SdlShowCursor)(engine + LX_SDL_SHOW_CURSOR_ADDR);
    add_event_watch = (AddEventWatch)(engine + LX_SDL_ADD_EVENT_WATCH_ADDR);
    return 1;
}

static int initialized;

/* Full startup: fingerprint, bindings, engine hooks. Called from the shared
 * object's constructor when LD_PRELOADed before the game starts, and from
 * luaopen_pstcontroller when a Lua environment manages to loadlib us. */
static int bridge_initialize(void) {
    if (initialized) return 1;
    loader_log = open_side_log("controller-loader.log");
    loader_note("Controller Lab native bridge 0.3.0 (Linux)");
    if (!controller_lab_profile()) {
        loader_note("Refused: the isolated Controller Lab profile is missing");
        return 0;
    }
    if (!initialize_bindings()) {
        loader_note("Refused: unsupported executable fingerprint");
        return 0;
    }
    if (!sdl_init_subsystems()) {
        loader_note("Warning: SDL_Init(joystick|gamecontroller) failed; retrying at first poll");
    } else {
        int count = ((int (*)(void))((uintptr_t)engine + LX_SDL_NUM_JOYSTICKS_ADDR))();
        char line[64];
        int n = snprintf(line, sizeof(line), "SDL joystick+gamecontroller up; joysticks=%d", count);
        if (n > 0 && n < (int)sizeof(line)) loader_note(line);
    }
    if (!install_process_events_filter()) {
        loader_note("Refused: CChitin::ProcessEvents prologue mismatch");
        return 0;
    }
    if (!install_set_pointer_filter()) {
        loader_note("Refused: CVidMode::SetPointer prologue mismatch");
        return 0;
    }
    if (!install_ui_do_file_logger()) {
        loader_note("Refused: uiDoFile prologue mismatch");
        return 0;
    }
    runtime_log = open_side_log("controller-runtime.log");
    /* If the Lua state already exists (loadlib path), register now;
     * otherwise bootstrapLua's hook does it once the state is built. */
    register_bridge(*(void **)(engine + LX_G_LUA_ADDR));
    if (!bridge_registered && !install_bootstrap_hook()) {
        loader_note("Refused: bootstrapLua prologue mismatch");
        return 0;
    }
    loader_note(bridge_registered
        ? "Bridge registered on the running Lua state"
        : "bootstrapLua hook installed; registration follows state creation");
    initialized = 1;
    return 1;
}

/* Only the game itself should activate the bridge; the shared object is also
 * linked into the model tests, which must stay untouched. */
static int host_is_torment(void) {
    char path[4096];
    ssize_t length = readlink("/proc/self/exe", path, sizeof(path) - 1);
    if (length <= 0 || (size_t)length >= sizeof(path) - 1) return 0;
    path[length] = 0;
    const char *slash = strrchr(path, '/');
    const char *leaf = slash ? slash + 1 : path;
    return strcmp(leaf, "Torment") == 0;
}

__attribute__((constructor))
static void pstcontroller_preload(void) {
    if (!host_is_torment()) return;
    bridge_initialize();
}

__attribute__((visibility("default")))
int luaopen_pstcontroller(lua_State *state) {
    if (!initialized && !bridge_initialize()) return 0;
    /* The constructor already registered the global through the engine
     * hook; a package.loadlib caller still receives the dispatch closure. */
    push_closure(state, dispatch, 0);
    return 1;
}
